'use client';import {useMemo,useState} from 'react';import {products} from '@/data/products';import {ProductGrid} from '@/components/product-card';
export default function Shop(){const[cat,setCat]=useState('all');const[sort,setSort]=useState('new');const list=useMemo(()=>products.filter(p=>cat==='all'||p.category===cat).sort((a,b)=>sort==='asc'?a.price-b.price:sort==='desc'?b.price-a.price:Number(b.isNew)-Number(a.isNew)),[cat,sort]);return <main className="container-x py-16"><p className="eyebrow text-brown">SPHINX Store</p><h1 className="display text-5xl mt-3">Магазин</h1><div className="flex flex-wrap justify-between gap-4 my-10 border-y py-5 border-black/10"><select className="bg-transparent" value={cat} onChange={e=>setCat(e.target.value)}><option value="all">Все категории</option><option value="t-shirts">Футболки</option><option value="hoodies">Худи</option><option value="sweatshirts">Свитшоты</option><option value="sport">Спорт</option></select><div className="flex gap-5 text-sm text-muted"><span>Размер: Все</span><span>Цвет: Все</span><span>Цена: Все</span></div><select className="bg-transparent" value={sort} onChange={e=>setSort(e.target.value)}><option value="new">Новинки</option><option value="asc">Цена: по возрастанию</option><option value="desc">Цена: по убыванию</option></select></div><ProductGrid products={list}/></main>}
